using System.IO;using System.Text.Json;namespace SmartRAM;
public record BaselineMetrics(DateTime CapturedAt,int Samples,double PeakPhysicalLoad,double AveragePhysicalLoad,double AverageAvailableMb,double AverageCommit,double PeakCommit,double AverageDiskLatency,double AveragePageReads);
public record ImpactComparison(BaselineMetrics Before,BaselineMetrics After,double AvailableMbGain,double PhysicalLoadChange,double CommitChange,double LatencyChange,double PageReadsChange,string Verdict);
public static class ImpactStore{static string Dir=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SmartRAM");static string BeforePath=>Path.Combine(Dir,"baseline-before.json");public static void SaveBefore(BaselineMetrics m){Directory.CreateDirectory(Dir);File.WriteAllText(BeforePath,JsonSerializer.Serialize(m,new JsonSerializerOptions{WriteIndented=true}));}public static BaselineMetrics? LoadBefore(){try{return File.Exists(BeforePath)?JsonSerializer.Deserialize<BaselineMetrics>(File.ReadAllText(BeforePath)):null;}catch{return null;}}public static ImpactComparison Compare(BaselineMetrics b,BaselineMetrics a){double avail=a.AverageAvailableMb-b.AverageAvailableMb,load=a.AveragePhysicalLoad-b.AveragePhysicalLoad,commit=a.AverageCommit-b.AverageCommit,lat=a.AverageDiskLatency-b.AverageDiskLatency,reads=a.AveragePageReads-b.AveragePageReads;int better=(avail>256?1:0)+(load<-3?1:0)+(commit<-3?1:0)+(lat<-2?1:0)+(reads<-5?1:0),worse=(avail<-256?1:0)+(load>3?1:0)+(commit>3?1:0)+(lat>2?1:0)+(reads>5?1:0);return new(b,a,avail,load,commit,lat,reads,better>worse?"Measured indicators improved":worse>better?"Measured indicators worsened":"No clear measured change");}}
public sealed class MeasurementSession{readonly List<PerformanceSnapshot> samples=new();readonly List<double> loads=new();public bool Running{get;private set;}public void Start(){samples.Clear();loads.Clear();Running=true;}public void Add(PerformanceSnapshot s,double load){if(Running){samples.Add(s);loads.Add(load);}}public BaselineMetrics? Stop(){Running=false;if(samples.Count<5)return null;return new(DateTime.Now,samples.Count,loads.Max(),loads.Average(),samples.Average(x=>x.AvailableMb),samples.Average(x=>x.CommitPercent),samples.Max(x=>x.CommitPercent),samples.Average(x=>x.DiskLatencyMs),samples.Average(x=>x.PageReadsPerSec));}}
